-- Hellfire Peninsula: creature abilities
-- Most of the zone's creatures (the Bonechewer and Bleeding Hollow orcs, the Burning Legion, the Shattered Hand, the wildlife) had
-- no AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm data; rows
-- needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted. The
-- creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '16879,16880,16915,16927,16928,16929,16939,16946,16947,16959,16960,16966,16967,16968,16974,16975,16977,16978,17084,18677,18679,18706,18733,18827,18828,18944,18945,18946,18948,18949,18950,18965,18966,18969,18971,18972,18974,18975,18976,18977,18978,18986,19006,19007,19188,19257,19258,19261,19263,19282,19298,19299,19335,19349,19350,19399,19408,19414,19424,19527,19681,20159,20238,20617,20798,21308,22258,22259,22267,22323,22507,26216,26222,26223';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '14881,15242,16579,16582,16600,16821,16831,16843,16864,17282,18758,19005,19363,19392,19397,19398,19400,19423,19443,19460,19864,20137,21306,22273,51799,51800,51903,51904,51907';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
